oxy_webhelp_navlinks = {"isolated_rubrik_clusters-d39307e11955":{"topics":[{"title":"Key features of isolated Rubrik clusters","shortdesc":"<p class=\"shortdesc\">Isolated Rubrik target clusters offer enhanced security by managing incoming traffic         to the target Rubrik cluster and handling snapshot replication efficiently.<\/p>","href":"replication\/rep_key_features_isolated_clusters.html","attributes":{"data-id":"rep_key_features_isolated_clusters"},"menu":{"hasChildren":false},"tocID":"rep_key_features_isolated_clusters-d39307e11966","topics":[]},{"title":"Management of isolated Rubrik clusters using <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\">The management of isolated Rubrik clusters using <span class=\"ph\">Rubrik Security Cloud<\/span> involves         establishing a brief, initial connection to the Rubrik cluster for configuration, updates,         and data synchronization, managing SLA Domains, and opening port 443.<\/p>","href":"replication\/mgmt_isolated_rubrik_clusters_rsc.html","attributes":{"data-id":"mgmt_isolated_rubrik_clusters_rsc"},"menu":{"hasChildren":false},"tocID":"mgmt_isolated_rubrik_clusters_rsc-d39307e11977","topics":[]},{"title":"Marking a Rubrik cluster as isolated","shortdesc":"<p class=\"shortdesc\">To secure your data by keeping a cluster protected behind a firewall and disconnected         from the network, mark a Rubrik cluster as isolated.<\/p>","href":"replication\/marking_rubrik_cluster_isolated.html","attributes":{"data-id":"marking_rubrik_cluster_isolated"},"menu":{"hasChildren":false},"tocID":"marking_rubrik_cluster_isolated-d39307e11993","topics":[]},{"title":"Marking an isolated Rubrik cluster as not isolated","shortdesc":"<p class=\"shortdesc\">To remove the isolation status of a Rubrik cluster, mark it as not isolated. This         allows inbound traffic and enables the cluster to be used for replication, without the data         protection restrictions of an isolated environment.<\/p>","href":"replication\/marking_isolated_rubrik_cluster_not_isolated.html","attributes":{"data-id":"marking_isolated_rubrik_cluster_not_isolated"},"menu":{"hasChildren":false},"tocID":"marking_isolated_rubrik_cluster_not_isolated-d39307e12004","topics":[]},{"title":"Benefits of marking an isolated Rubrik cluster as not isolated","shortdesc":"<p class=\"shortdesc\">Marking an isolated Rubrik cluster as not isolated enhances network connectivity,         data redundancy through replication, and simplifies cluster management.<\/p>","href":"replication\/benefits_marking_isolated_rubrik_cluster_not_isolated.html","attributes":{"data-id":"benefits_marking_isolated_rubrik_cluster_not_isolated"},"menu":{"hasChildren":false},"tocID":"benefits_marking_isolated_rubrik_cluster_not_isolated-d39307e12015","topics":[]},{"title":"Isolated Rubrik cluster limitations","shortdesc":"<p class=\"shortdesc\">Isolated Rubrik clusters have some limitations due to their disconnected state,         including constraints on managing and protecting workloads.<\/p>","href":"replication\/isolated_rubrik_cluster_limitations.html","attributes":{"data-id":"isolated_rubrik_cluster_limitations"},"menu":{"hasChildren":false},"tocID":"isolated_rubrik_cluster_limitations-d39307e12026","topics":[]},{"title":"Isolated Rubrik cluster operational capabilities","shortdesc":"<p class=\"shortdesc\">Information about the operations that you can and cannot perform on isolated Rubrik         clusters when they are not connected to the <span class=\"ph\">RSC<\/span>. The source clusters are         required to be connected to <span class=\"ph\">RSC<\/span> to perform all operations.<\/p>","href":"replication\/isolated_rubrik_cluster_operations.html","attributes":{"data-id":"rubrik_isolated_cluster_operations"},"menu":{"hasChildren":false},"tocID":"rubrik_isolated_cluster_operations-d39307e12037","topics":[]}]}};